package com.nigson.commerce.inventory;
import java.util.*;
import java.math.*;
import java.time.Clock;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
public final class JdbcInventoryRepository implements InventoryRepository {
 private final JdbcTemplate jdbc;private final Clock clock;public JdbcInventoryRepository(JdbcTemplate jdbc,Clock clock){this.jdbc=jdbc;this.clock=clock;}
 private void transaction(){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("LOCAL_TRANSACTION_REQUIRED");}
 private InventoryValues.Stock stock(java.sql.ResultSet r)throws java.sql.SQLException{int scale=r.getInt("quantity_scale");var hand=r.getBigDecimal("on_hand");var reserved=r.getBigDecimal("reserved");var allocated=r.getBigDecimal("allocated");return new InventoryValues.Stock(r.getObject("sku_id",UUID.class),r.getObject("location_id",UUID.class),InventoryValues.wire(hand,scale),InventoryValues.wire(reserved,scale),InventoryValues.wire(allocated,scale),InventoryValues.wire(hand.subtract(reserved).subtract(allocated),scale),r.getLong("version"));}
 public InventoryValues.Page list(InventoryValues.Query query){String where=" WHERE (?::uuid IS NULL OR b.sku_id=?) AND (?::uuid IS NULL OR b.location_id=?)";var args=new Object[]{query.skuId(),query.skuId(),query.locationId(),query.locationId()};long count=jdbc.queryForObject("SELECT count(*) FROM commerce.inventory_balance b"+where,Long.class,args);String sort=switch(query.sort().split(",")[0]){case "skuId"->"b.sku_id";case "locationId"->"b.location_id";case "available"->"(b.on_hand-b.reserved-b.allocated)";default->throw ApiValues.invalid();};var parameters=new ArrayList<Object>(Arrays.asList(args));parameters.add(query.size());parameters.add((long)query.page()*query.size());var items=jdbc.query("SELECT b.*,s.quantity_scale FROM commerce.inventory_balance b JOIN commerce.sku s ON s.id=b.sku_id"+where+" ORDER BY "+sort+(query.sort().endsWith(",desc")?" DESC":" ASC")+",b.id ASC LIMIT ? OFFSET ?",(r,n)->stock(r),parameters.toArray());return new InventoryValues.Page(items,query.page(),query.size(),count,(count+query.size()-1)/query.size());}
 public InventoryValues.Location create(InventoryValues.NewLocation input,String actor){transaction();UUID id=EventCodec.uuid7(clock.instant());try{jdbc.update("INSERT INTO commerce.stock_location(id,created_by,updated_by,code,name) VALUES (?,?,?,?,?)",id,actor,actor,input.code(),input.name());}catch(org.springframework.dao.DuplicateKeyException duplicate){throw new Problem.Failure(ProblemCode.CONFLICT);}return new InventoryValues.Location(id,input.code(),input.name(),true,0);}
 public Changed adjust(InventoryValues.Adjustment input,long expected,String operation,String actor){transaction();var locations=jdbc.query("SELECT id FROM commerce.stock_location WHERE id=? AND active FOR SHARE",(r,n)->r.getObject(1,UUID.class),input.locationId());if(locations.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);
  var scales=jdbc.query("SELECT quantity_scale FROM commerce.sku WHERE id=? AND active AND deleted_at IS NULL FOR SHARE",(r,n)->r.getInt(1),input.skuId());if(scales.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);BigDecimal delta=InventoryValues.quantity(input.delta(),scales.getFirst(),true);
  jdbc.update("INSERT INTO commerce.inventory_balance(id,created_by,updated_by,sku_id,location_id) VALUES (?,?,?,?,?) ON CONFLICT(sku_id,location_id) DO NOTHING",EventCodec.uuid7(clock.instant()),actor,actor,input.skuId(),input.locationId());
  var row=jdbc.queryForMap("SELECT * FROM commerce.inventory_balance WHERE sku_id=? AND location_id=? FOR UPDATE",input.skuId(),input.locationId());UUID id=(UUID)row.get("id");long version=((Number)row.get("version")).longValue();if(expected!=version)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);
  BigDecimal hand=(BigDecimal)row.get("on_hand"),reserved=(BigDecimal)row.get("reserved"),allocated=(BigDecimal)row.get("allocated"),next=hand.add(delta);if(next.compareTo(reserved.add(allocated))<0||next.compareTo(InventoryValues.MAX)>0)throw InventoryValues.rule();int scale=scales.getFirst();var before=new InventoryValues.Stock(input.skuId(),input.locationId(),InventoryValues.wire(hand,scale),InventoryValues.wire(reserved,scale),InventoryValues.wire(allocated,scale),InventoryValues.wire(hand.subtract(reserved).subtract(allocated),scale),version);
  jdbc.update("INSERT INTO commerce.inventory_movement(id,created_by,balance_id,operation_key,movement_type,delta_on_hand,delta_reserved,delta_allocated,reason) VALUES (?,?,?,?,'ADJUST',?,0,0,?)",EventCodec.uuid7(clock.instant()),actor,id,operation,delta,input.reason());jdbc.update("UPDATE commerce.inventory_balance SET on_hand=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",next,java.sql.Timestamp.from(clock.instant()),actor,id);
  var after=new InventoryValues.Stock(input.skuId(),input.locationId(),InventoryValues.wire(next,scale),before.reserved(),before.allocated(),InventoryValues.wire(next.subtract(reserved).subtract(allocated),scale),version+1);return new Changed(id,before,after);
 }
}
